// @vitest-environment jsdom
import { describe, expect, it } from 'vitest';
import { AppUI } from './index';
import { AppUI as LegacyAppUI } from './__legacy';

const screens = ['main', 'settings', 'profile', 'play', 'custom', 'ranked'];

describe('AppUI formatting parity', () => {
  it('renders identical markup on every screen', () => {
    for (const screen of screens) {
      const a = document.createElement('div');
      const b = document.createElement('div');
      new AppUI(a).navigate(screen as never);
      new LegacyAppUI(b).navigate(screen as never);
      expect(a.innerHTML).toBe(b.innerHTML);
    }
  });

  it('renders identical markup for an explicit course', () => {
    const a = document.createElement('div');
    const b = document.createElement('div');
    new AppUI(a, {}, { initialCourseId: 'volcano' }).navigate('custom' as never);
    new LegacyAppUI(b, {}, { initialCourseId: 'volcano' }).navigate('custom' as never);
    expect(a.innerHTML).toBe(b.innerHTML);
  });
});
EOF
npx vitest run src/ui/__parity.test.ts 2>&1 | tail -14
